{"implementation":"def solve(case):
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError("Missing required fields")
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_dict = {}
    children = {}
    for node in nodes:
        nid = node.get('id')
        for key in ('id','parent','symbol','depth','removable','utility'):
            if key not in node:
                raise ValueError(f"Node {nid} missing {key}")
        node_dict[nid] = node
        children[nid] = []
    for node in nodes:
        pid = node['parent']
        if pid is not None:
            children[pid].append(node['id'])
    current = set(node_dict.keys())
    candidate_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for node in candidate_nodes:
        nid = node['id']
        if not node['removable'] or nid not in current:
            continue
        subtree = set()
        stack = [nid]
        while stack:
            cur = stack.pop()
            if cur in current and cur not in subtree:
                subtree.add(cur)
                for child in children.get(cur, []):
                    stack.append(child)
        remaining_symbols = {}
        for n in node_dict.values():
            if n['id'] in current and n['id'] not in subtree:
                sym = n['symbol']
                remaining_symbols[sym] = remaining_symbols.get(sym, 0) + 1
        valid = all(remaining_symbols.get(req, 0) > 0 for req in required_symbols)
        if valid:
            current.difference_update(subtree)
            removed.append(nid)
    retained = sorted(current)
    return {"removed_node_ids": removed, "retained_node_ids": retained}"}
